def _compute_field_value(self, field: Field) -> None:
    determine(field.compute, self)

    if field.store and any(self._ids):
        # check constraints of the fields that have been computed
        fnames = [f.name for f in self.pool.field_computed[field]]
        self.filtered('id')._validate_fields(fnames)

def compute_value(self, records: BaseModel) -> None:
    """ Invoke the compute method on ``records``; the results are in cache. """
    env = records.env
    if self.compute_sudo:
        records = records.sudo()
    fields = records.pool.field_computed[self]

    # Just in case the compute method does not assign a value, we already
    # mark the computation as done. This is also necessary if the compute
    # method accesses the old value of the field: the field will be fetched
    # with _read(), which will flush() it. If the field is still to compute,
    # the latter flush() will recursively compute this field!
    for field in fields:
        if field.store:
            env.remove_to_compute(field, records)

    try:
        with records.env.protecting(fields, records):
            records._compute_field_value(self)
    except Exception:
        for field in fields:
            if field.store:
                env.add_to_compute(field, records)
        raise

def cache_key(self, field: Field) -> typing.Any:
    """ Return the cache key of the given ``field``. """
    def get(key, get_context=self.context.get):
        if key == 'company':
            return self.company.id
        elif key == 'uid':
            return self.uid if field.compute_sudo else (self.uid, self.su)
        elif key == 'lang':
            return get_context('lang') or None
        elif key == 'active_test':
            return get_context('active_test', field.context.get('active_test', True))
        elif key.startswith('bin_size'):
            return bool(get_context(key))
        else:
            val = get_context(key)
            if type(val) is list:
                val = tuple(val)
            try:
                hash(val)
            except TypeError:
                raise TypeError(
                    "Can only create cache keys from hashable values, "
                    f"got non-hashable value {val!r} at context key {key!r} "
                    f"(dependency of field {field})"
                ) from None  # we don't need to chain the exception created 2 lines above
            else:
                return val

    return tuple(get(key) for key in self.registry.field_depends_context[field])

def _compute_full_name(self):
    # Important: value must be stored in environment of group, not group1!
    for group, group1 in zip(self, self.sudo()):
        if group1.privilege_id and not self.env.context.get('short_display_name'):
            group.full_name = '%s / %s' % (group1.privilege_id.name, group1.name)
        else:
            group.full_name = group1.name
